  "preview_blurb": "老街广播站突发断电，维修员与主持人在焦急排查中从互相猜疑走向默契，却在通电前夕遭遇意外阻碍。",
  "scenes": [
    {
      "title": "断电与初见",
      "location": "广播站控制室",
      "dramatic_goal": "展现突发断电的危机，确立林岚与周野因焦急而产生的初步摩擦。",
      "lines": [
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "哎！怎么黑了？这机器又闹脾气？街坊还等着听评书呢！",
